with unpivoted as (select * from (select id, customer_id, discount, shipping_fee from orders) src unpivot (val for metric in (discount, shipping_fee))) select metric, size(collect_set(metric)) as num_metrics, sum(case when metric = 'shipping_fee' then val else 0 end) as shipping_fee_val, percentile_approx(val, 0.9) as val_p90, count(case when metric = 'discount' then 1 end) as discount_count, sum(case when metric = 'discount' then val else 0 end) as discount_val from unpivoted group by 1 order by val_p90 desc
